-- Issue #8: Budgets - PostgreSQL
-- Chạy script này trên đúng database của ứng dụng trước khi mở /Budgets.

CREATE TABLE IF NOT EXISTS "Budgets" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId" text NOT NULL,
    "CategoryId" integer NOT NULL,
    "Amount" numeric(18, 2) NOT NULL CHECK ("Amount" > 0),
    "Month" integer NOT NULL CHECK ("Month" BETWEEN 1 AND 12),
    "Year" integer NOT NULL CHECK ("Year" BETWEEN 2000 AND 2100),
    CONSTRAINT "FK_Budgets_AspNetUsers_UserId"
        FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Budgets_Categories_CategoryId"
        FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "UQ_Budgets_User_Category_Month_Year"
        UNIQUE ("UserId", "CategoryId", "Month", "Year")
);

CREATE INDEX IF NOT EXISTS "IX_Budgets_UserId_Year_Month"
    ON "Budgets" ("UserId", "Year", "Month");
